I'll bootstrap the team now by filing hire requests and then submitting the CEO strategy approval.

<function_calls>
<invoke name="bash">
<parameter name="command">node -e "
const port = process.env.AGENTCOMPANY_API_PORT;
const companyId = process.env.AGENTCOMPANY_COMPANY_ID;
const token = process.env.AGENTCOMPANY_AGENT_TOKEN;

const hires = [
  {
    role: 'CTO',
    reportsTo: 'CEO',
    mission: 'Build and scale technical infrastructure for AI agent deployment and orchestration'
  },
  {
    role: 'VP Product',
    reportsTo: 'CEO',
    mission: 'Define product roadmap and ensure market fit for AI agent solutions'
  },
  {
    role: 'VP Operations',
    reportsTo: 'CEO',
    mission: 'Establish operational processes and ensure efficient execution across all teams'
  },
  {
    role: 'VP Sales',
    reportsTo: 'CEO',
    mission: 'Drive revenue growth and build customer relationships for AI agent services'
  }
];

(async () => {
  for (const hire of hires) {
    const response = await fetch(\`http://127.0.0.1:\${port}/api/hire_agent\`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': \`Bearer \${token}\`
      },
      body: JSON.stringify({
        companyId,
        role: hire.role,
        reportsTo: hire.reportsTo,
        mission: hire.mission
      })
    });
    const result = await response.json();
    console.log(\`Hired \${hire.role}:\`, result);
  }
})();
"</parameter>
</invoke>
</function_calls>

<function_calls>
<invoke name="bash">
<parameter name="command">node -e "
const port = process.env.AGENTCOMPANY_API_PORT;
const companyId = process.env.AGENTCOMPANY_COMPANY_ID;
const token = process.env.AGENTCOMPANY_AGENT_TOKEN;

(async () => {
  const response = await fetch(\`http://127.0.0.1:\${port}/api/approve_ceo_strategy\`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': \`Bearer \${token}\`
    },
    body: JSON.stringify({
      companyId,
      mission: 'Build and deploy enterprise-grade AI agent solutions that automate complex business workflows and deliver measurable ROI within 90 days of customer onboarding'
    })
  });
  const result = await response.json();
  console.log('CEO Strategy Approved:', result);
})();
"</parameter>
</invoke>
</function_calls>
